#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common PolyBench-style definitions (DATA_TYPE, N, TSTEPS, etc)
#include "defines.hpp"

// include benchmark-specific definitions
#include "heat-3d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Array initialization, translated to Halide.
static void init_array(int n,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 3> B) {
    // C layout is A[i][j][k] with i (slow), j, k (fast).
    // We map to Halide Buffer(k, j, i) so that k is the fastest-varying dim.
    Var k("k"), j("j"), i("i");
    Func init("init");

    // Original C:
    // A[i][j][k] = B[i][j][k] =
    //   (DATA_TYPE) (i + j + (n-k)) * 10 / (n);
    Expr i_j_k = i + j + (n - k);
    Expr val = cast<num_t>(i_j_k) * cast<num_t>(Expr(10.0)) /
               cast<num_t>(Expr((double)n));

    init(k, j, i) = val;

    init.realize(A);
    init.realize(B);
}

int main(int argc, char *argv[]) {
    // problem size
    int n = N;
    int tsteps = TSTEPS;

    // Buffers for A and B.
    // Dimension order is (k, j, i) to match C's A[i][j][k] in row-major layout.
    Halide::Buffer<num_t, 3> A_buf(n, n, n);
    Halide::Buffer<num_t, 3> B_buf(n, n, n);

    // initialize data
    init_array(n, A_buf, B_buf);

    // Halide pipeline for one half-step: A -> B (update interior of B using A).
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam B_param(type_of<num_t>(), 3, "B_param");  // used for B -> A step

    Var x("x"), y("y"), z("z");
    Func step_A_to_B("step_A_to_B");
    Func step_B_to_A("step_B_to_A");

    // x, y, z are indices for the *interior* grid, 0..(n-3).
    // Map to actual i,j,k indices in C:
    //   i = z + 1, j = y + 1, k = x + 1
    Expr ii = z + 1;
    Expr jj = y + 1;
    Expr kk = x + 1;

    // Constants: 0.125 and 2.0, in the correct scalar type
    Expr c0_125 = cast<num_t>(Expr(0.125));
    Expr c2_0   = cast<num_t>(Expr(2.0));

    // Stencil for B[i][j][k] from A
    {
        Expr centerA = A_param(kk, jj, ii);

        Expr term_i =
            c0_125 *
            (A_param(kk, jj, ii + 1) - c2_0 * centerA + A_param(kk, jj, ii - 1));

        Expr term_j =
            c0_125 *
            (A_param(kk, jj + 1, ii) - c2_0 * centerA + A_param(kk, jj - 1, ii));

        Expr term_k =
            c0_125 *
            (A_param(kk + 1, jj, ii) - c2_0 * centerA + A_param(kk - 1, jj, ii));

        step_A_to_B(x, y, z) = term_i + term_j + term_k + centerA;
    }

    // Stencil for A[i][j][k] from B
    {
        Expr centerB = B_param(kk, jj, ii);

        Expr term_i =
            c0_125 *
            (B_param(kk, jj, ii + 1) - c2_0 * centerB + B_param(kk, jj, ii - 1));

        Expr term_j =
            c0_125 *
            (B_param(kk, jj + 1, ii) - c2_0 * centerB + B_param(kk, jj - 1, ii));

        Expr term_k =
            c0_125 *
            (B_param(kk + 1, jj, ii) - c2_0 * centerB + B_param(kk - 1, jj, ii));

        step_B_to_A(x, y, z) = term_i + term_j + term_k + centerB;
    }

    // Preserve original traversal order: k innermost, then j, then i.
    // Our Buffer layout (k,j,i) already matches that, so we can just
    // reorder the Vars to reflect that for clarity.
    step_A_to_B.reorder(x, y, z);
    step_B_to_A.reorder(x, y, z);

    // Compile the kernels once.
    step_A_to_B.compile_jit();
    step_B_to_A.compile_jit();

    // Buffers for the interior computations: size (n-2)^3 over indices
    //   i = 1..n-2, j = 1..n-2, k = 1..n-2
    int interior = n - 2;
    Halide::Buffer<num_t, 3> B_interior(interior, interior, interior);
    Halide::Buffer<num_t, 3> A_interior(interior, interior, interior);

    // Time-stepping loop, driven from the host. This mirrors:
    //
    // for (t = 1; t <= TSTEPS; t++) {
    //   B[...] = stencil(A[...]);
    //   A[...] = stencil(B[...]);
    // }
    //
    // We only compute the interior points with Halide and leave the
    // boundary values unchanged, just as in the original C code.
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tsteps; t++) {
        // A -> B
        A_param.set(A_buf);
        step_A_to_B.realize(B_interior);

        // Copy interior (i=1..n-2, j=1..n-2, k=1..n-2) back into B_buf.
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < n - 1; j++) {
                for (int k = 1; k < n - 1; k++) {
                    int kk0 = k - 1; // interior index
                    int jj0 = j - 1;
                    int ii0 = i - 1;
                    B_buf(k, j, i) = B_interior(kk0, jj0, ii0);
                }
            }
        }

        // B -> A
        B_param.set(B_buf);
        step_B_to_A.realize(A_interior);

        // Copy interior (i=1..n-2, j=1..n-2, k=1..n-2) back into A_buf.
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < n - 1; j++) {
                for (int k = 1; k < n - 1; k++) {
                    int kk0 = k - 1; // interior index
                    int jj0 = j - 1;
                    int ii0 = i - 1;
                    A_buf(k, j, i) = A_interior(kk0, jj0, ii0);
                }
            }
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the final A for debugging / DCE prevention.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    std::cerr << A_buf(k, j, i) << '\n';
                }
            }
        }
    }

    // Print execution time in seconds (like gemm.cpp)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
