#include "Halide.h"

// include common definitions (DATA_TYPE, N, TSTEPS, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "heat-3d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Array initialization.
 *
 * Original C:
 *   for (i, j, k)
 *     A[i][j][k] = B[i][j][k] = (i + j + (n-k)) * 10 / n;
 *
 * Mapping to Halide:
 *   C array A[i][j][k] -> Buffer A(k, j, i)
 *   so we realize over (k, j, i) with extents (n, n, n).
 */
static
void init_array(int n,
                Halide::Buffer<num_t, 3> A,
                Halide::Buffer<num_t, 3> B) {
    Var i("i"), j("j"), k("k");
    Func init_A("init_A"), init_B("init_B");

    // n as a Halide Expr
    Expr n_expr = Expr(n);

    // Compute the same value as the C code:
    // (i + j + (n - k)) * 10 / n
    Expr val_int = i + j + (n_expr - k);
    Expr val = cast<num_t>(val_int) *
               cast<num_t>(Expr(10)) /
               cast<num_t>(n_expr);

    // Remember: Buffer layout is (k, j, i)
    init_A(k, j, i) = val;
    init_B(k, j, i) = val;

    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem sizes (from PolyBench)
    int n      = N;
    int tsteps = TSTEPS;

    // Buffers for A and B.
    // C layout: A[i][j][k] with k innermost.
    // Halide Buffer: A(k, j, i) with dimension 0 fastest.
    Halide::Buffer<num_t, 3> A(n, n, n);
    Halide::Buffer<num_t, 3> B(n, n, n);

    // Initialize arrays.
    init_array(n, A, B);

    // Define a single time-step 3D heat stencil in Halide.
    //
    // This computes:
    //   out = f(in)
    //
    // with:
    //   out[i][j][k] = 0.125 * (in[i+1][j][k] - 2*in[i][j][k] + in[i-1][j][k])
    //                + 0.125 * (in[i][j+1][k] - 2*in[i][j][k] + in[i][j-1][k])
    //                + 0.125 * (in[i][j][k+1] - 2*in[i][j][k] + in[i][j][k-1])
    //                + in[i][j][k];
    //
    // We express this as a Func "heat" that takes an ImageParam "A_param"
    // as input, and produces an updated 3D field. Boundaries are copied
    // directly from the input, and only the interior [1..n-2] is updated.
    Var k("k"), j("j"), i("i");
    ImageParam A_param(type_of<num_t>(), 3, "A_param");

    Func heat("heat");

    // Default: copy input to output everywhere.
    heat(k, j, i) = A_param(k, j, i);

    // Interior update region: 1 .. extent-2 on each dimension.
    RDom r(1, A_param.dim(0).extent() - 2,
           1, A_param.dim(1).extent() - 2,
           1, A_param.dim(2).extent() - 2,
           "r");

    Expr center = A_param(r.x,     r.y,     r.z);
    Expr two    = cast<num_t>(Expr(2.0));
    Expr coeff  = cast<num_t>(Expr(0.125));

    // Differences along each axis.
    Expr dx = A_param(r.x + 1, r.y,     r.z) - two * center +
              A_param(r.x - 1, r.y,     r.z);
    Expr dy = A_param(r.x,     r.y + 1, r.z) - two * center +
              A_param(r.x,     r.y - 1, r.z);
    Expr dz = A_param(r.x,     r.y,     r.z + 1) - two * center +
              A_param(r.x,     r.y,     r.z - 1);

    heat(r.x, r.y, r.z) = coeff * dx + coeff * dy + coeff * dz + center;

    // Simple schedule: compute the whole 3D result at once.
    heat.compute_root();

    // Bind the input for compilation.
    A_param.set(A);

    // JIT-compile the kernel.
    heat.compile_jit();

    // Time stepping loop, matching the C code:
    //
    // for (t = 1; t <= TSTEPS; t++) {
    //   B = f(A);
    //   A = f(B);
    // }
    using clock = std::chrono::high_resolution_clock;
    auto start = clock::now();

    for (int t = 0; t < tsteps; t++) {
        // B[i][j][k] = f(A)
        A_param.set(A);
        heat.realize(B);

        // A[i][j][k] = f(B)
        A_param.set(B);
        heat.realize(A);
    }

    auto end = clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the output array to stderr, similar to PolyBench's
    // print_array (but without formatting constraints).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                for (int kk = 0; kk < n; kk++) {
                    // Remember mapping: A(i,j,k) in C -> A(kk, jj, ii) in Halide.
                    std::cerr << A(kk, jj, ii) << '\n';
                }
            }
        }
    }

    // Print execution time in seconds, similar style to the gemm example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
