#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, TSTEPS, etc)
#include "defines.hpp"

// include benchmark-specific definitions
#include "heat-3d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize the 3D arrays A and B.
 *
 * Original C:
 *   for i, j, k:
 *     A[i][j][k] = B[i][j][k] = (i + j + (n-k)) * 10 / n;
 *
 * Mapping to Halide:
 *   C index  A[i][j][k]
 *   -> Buffer index A(k, j, i)
 *   (k is fastest-varying dimension, then j, then i)
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 3> B) {
    Var i("i"), j("j"), k("k");

    Func init_A("init_A"), init_B("init_B");

    Expr n_expr = Expr(n);
    Expr value = cast<num_t>((i + j + (n_expr - k)) * Expr(10)) /
                 cast<num_t>(n_expr);

    // Map C's A[i][j][k] to Halide's A(k, j, i)
    init_A(k, j, i) = value;
    init_B(k, j, i) = value;

    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int tsteps = TSTEPS;

    // Buffers corresponding to C arrays:
    //   DATA_TYPE A[N][N][N], B[N][N][N]
    //
    // Mapping:
    //   A[i][j][k]  <->  A_buf(k, j, i)
    Halide::Buffer<num_t, 3> A(n, n, n);
    Halide::Buffer<num_t, 3> B(n, n, n);

    // Initialize arrays
    init_array(n, A, B);

    // ------------------------------------------------------------------------
    // Define a single time-step of the 3D heat stencil as a Halide pipeline.
    //
    // Original C kernel (one "half step"):
    //
    //   for (i = 1; i < n-1; i++)
    //     for (j = 1; j < n-1; j++)
    //       for (k = 1; k < n-1; k++)
    //         B[i][j][k] =
    //             0.125 * (A[i+1][j][k] - 2.0*A[i][j][k] + A[i-1][j][k]) +
    //             0.125 * (A[i][j+1][k] - 2.0*A[i][j][k] + A[i][j-1][k]) +
    //             0.125 * (A[i][j][k+1] - 2.0*A[i][j][k] + A[i][j][k-1]) +
    //             A[i][j][k];
    //
    // Boundaries (i==0, i==n-1, etc) are never written, so they remain at
    // their initialized values for all time steps.
    //
    // We express a single step as:
    //
    //   dest = heat_step(src)
    //
    // implemented by:
    //   heat_step(k, j, i) = select(interior(i,j,k), stencil(src), src)
    //
    // and drive the time loop from the host using double buffering:
    //
    //   for t in 1..TSTEPS:
    //     B = heat_step(A)
    //     A = heat_step(B)
    //
    // Note: we use an ImageParam for the current state ("cur") and
    //       a Param<int> for 'n', as per the DP guidance in the rules.
    // ------------------------------------------------------------------------

    ImageParam cur(type_of<num_t>(), 3, "cur");   // current 3D field
    Param<int> n_param("n_param");

    Var k("k"), j("j"), i("i");

    // Clamp coordinates to implement a repeat-edge boundary condition,
    // so that accesses like cur(k+1, j, i) are always in-bounds.
    Func cur_bc("cur_bc");
    {
        Expr n_e = n_param;

        Expr kk = clamp(k, 0, n_e - 1);
        Expr jj = clamp(j, 0, n_e - 1);
        Expr ii = clamp(i, 0, n_e - 1);

        cur_bc(k, j, i) = cur(kk, jj, ii);
    }

    Func heat_step("heat_step");

    // Constants in the correct Halide Expr form
    Expr c125 = cast<num_t>(Expr(0.125));
    Expr two  = cast<num_t>(Expr(2.0));

    Expr center = cur_bc(k, j, i);

    Expr stencil =
        c125 * (cur_bc(k + 1, j, i) - two * center + cur_bc(k - 1, j, i)) +
        c125 * (cur_bc(k, j + 1, i) - two * center + cur_bc(k, j - 1, i)) +
        c125 * (cur_bc(k, j, i + 1) - two * center + cur_bc(k, j, i - 1)) +
        center;

    // Interior condition: 1 <= i, j, k <= n-2
    Expr interior =
        (i >= 1) && (i < n_param - 1) &&
        (j >= 1) && (j < n_param - 1) &&
        (k >= 1) && (k < n_param - 1);

    // For interior points, apply the stencil; for boundary points,
    // just keep the old value (matching the C code semantics).
    heat_step(k, j, i) = select(interior, stencil, cur(k, j, i));

    // The default schedule for heat_step(k, j, i) gives loops:
    //   for i
    //     for j
    //       for k
    // which matches the original C loop order (i, j, k), so we don't
    // need to add any explicit reordering here.

    // Bind the problem size parameter
    n_param.set(n);

    // Compile the pipeline once ahead of time; we'll re-use it for all
    // time steps by rebinding 'cur' and realizing into A/B.
    heat_step.compile_jit();

    // ------------------------------------------------------------------------
    // Run the time-stepping loop, measuring only execution time (not JIT).
    // ------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 1; t <= tsteps; t++) {
        // First half-step: B = heat_step(A)
        cur.set(A);
        heat_step.realize(B);

        // Second half-step: A = heat_step(B)
        cur.set(B);
        heat_step.realize(A);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // ------------------------------------------------------------------------
    // Print the output (A) to prevent dead-code elimination and optionally
    // check correctness. We follow the pattern from the GEMM example and
    // print every element on its own line.
    // ------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                for (int kk = 0; kk < n; kk++) {
                    // C's A[ii][jj][kk]  <->  Halide's A(kk, jj, ii)
                    std::cerr << A(kk, jj, ii) << '\n';
                }
            }
        }
    }

    // Print the elapsed time in seconds (as in the GEMM example)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
