#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, TSTEPS, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "heat-3d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Array initialization using Halide Funcs.
static void init_array(int n,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 3> B) {
    // C code indices: A[i][j][k]
    // We map to Halide as A(k, j, i) with shape (n, n, n).

    Var i("i"), j("j"), k("k");
    Func init_val("init_val");

    // Original C:
    // A[i][j][k] = B[i][j][k] =
    //   (DATA_TYPE)(i + j + (n - k)) * 10 / (n);
    Expr tmp = i + j + (n - k);
    Expr val = cast<num_t>(tmp) * (num_t)10 / cast<num_t>(n);

    init_val(k, j, i) = val;

    init_val.realize(A);
    init_val.realize(B);
}

int main(int argc, char *argv[]) {
    // problem size
    int n      = N;
    int tsteps = TSTEPS;

    // Buffers:
    // C arrays are A[i][j][k], B[i][j][k], i,j,k in [0, n)
    // Map to Halide as:
    //   dim 0: k (innermost)
    //   dim 1: j
    //   dim 2: i (outermost)
    Halide::Buffer<num_t, 3> A(n, n, n);
    Halide::Buffer<num_t, 3> B(n, n, n);

    // Initialize data
    init_array(n, A, B);

    // Set up Halide pipeline for a single stencil update:
    //
    // This implements one of the two updates in kernel_heat_3d:
    //
    //   out[i][j][k] =
    //       0.125 * (in[i+1][j][k] - 2*in[i][j][k] + in[i-1][j][k]) +
    //       0.125 * (in[i][j+1][k] - 2*in[i][j][k] + in[i][j-1][k]) +
    //       0.125 * (in[i][j][k+1] - 2*in[i][j][k] + in[i][j][k-1]) +
    //       in[i][j][k];
    //
    // We will apply this twice per time step: A -> B, then B -> A,
    // exactly matching the original C code.

    ImageParam input(type_of<num_t>(), 3, "input");

    Var x("x"), y("y"), z("z");

    // Wrap the input with a boundary condition so that neighbor
    // accesses are always in-bounds, even near the edges.
    Func clamped = BoundaryConditions::repeat_edge(input);

    // Compute min/max of each dimension from the input itself.
    Expr x_min = input.dim(0).min();
    Expr y_min = input.dim(1).min();
    Expr z_min = input.dim(2).min();

    Expr x_extent = input.dim(0).extent();
    Expr y_extent = input.dim(1).extent();
    Expr z_extent = input.dim(2).extent();

    Expr x_max = x_min + x_extent - 1;
    Expr y_max = y_min + y_extent - 1;
    Expr z_max = z_min + z_extent - 1;

    // Interior region: i,j,k in [1, n-2] in C
    // Here: z corresponds to i, y to j, x to k.
    Expr is_interior =
        (x > x_min) && (x < x_max) &&
        (y > y_min) && (y < y_max) &&
        (z > z_min) && (z < z_max);

    Func heat_step("heat_step");

    Expr center = input(x, y, z);
    Expr alpha  = cast<num_t>(0.125);
    Expr two    = cast<num_t>(2.0);

    // Neighbor accesses:
    // i +/- 1 -> z +/- 1
    // j +/- 1 -> y +/- 1
    // k +/- 1 -> x +/- 1
    Expr term_i = alpha * (clamped(x, y, z + 1) - two * center + clamped(x, y, z - 1));
    Expr term_j = alpha * (clamped(x, y + 1, z) - two * center + clamped(x, y - 1, z));
    Expr term_k = alpha * (clamped(x + 1, y, z) - two * center + clamped(x - 1, y, z));

    Expr update_val = term_i + term_j + term_k + center;

    // For interior points, apply the stencil; for boundary points,
    // keep the original value unchanged (matching the C code, which
    // never writes boundaries).
    heat_step(x, y, z) = select(is_interior, update_val, center);

    // Simple schedule: rely on Halide's default traversal order,
    // which corresponds to:
    //   for (z) for (y) for (x) ...
    Target target = get_host_target();
    heat_step.compile_jit(target);

    // Time the main computation (excluding JIT compilation).
    auto start = std::chrono::high_resolution_clock::now();

    // Perform the time-stepping:
    // Original C:
    // for (t = 1; t <= TSTEPS; t++) {
    //   B = stencil(A);
    //   A = stencil(B);
    // }
    for (int t = 1; t <= tsteps; t++) {
        // B[i][j][k] = stencil(A[i][j][k])
        input.set(A);
        heat_step.realize(B);

        // A[i][j][k] = stencil(B[i][j][k])
        input.set(B);
        heat_step.realize(A);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result, to roughly match PolyBench behavior.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    // A[i][j][k] -> A(k, j, i)
                    std::cerr << A(k, j, i) << '\n';
                }
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
